#!/usr/bin/env python3
import base64
from pathlib import Path

PLACEHOLDER_IMAGES = {
    "happy1.jpg": "data:image/jpeg;base64,",
    "happy2.jpg": "data:image/jpeg;base64,",
    "sad1.jpg": "data:image/jpeg;base64,",
    "sad2.jpg": "data:image/jpeg;base64,",
    "angry1.jpg": "data:image/jpeg;base64,",
    "angry2.jpg": "data:image/jpeg;base64,",
    "surprised1.jpg": "data:image/jpeg;base64,",
    "surprised2.jpg": "data:image/jpeg;base64,",
    "neutral1.jpg": "data:image/jpeg;base64,",
    "neutral2.jpg": "data:image/jpeg;base64,",
    "excited1.jpg": "data:image/jpeg;base64,",
    "excited2.jpg": "data:image/jpeg;base64,",
    "worried1.jpg": "data:image/jpeg;base64,",
    "worried2.jpg": "data:image/jpeg;base64,",
}

def create_placeholder_images():
    images_dir = Path("images")
    images_dir.mkdir(exist_ok=True)
    
    for filename, data_url in PLACEHOLDER_IMAGES.items():
        base64_data = data_url.split(',')[1]
        image_data = base64.b64decode(base64_data)
        with open(images_dir / filename, 'wb') as f:
            f.write(image_data)
        print(f"Created {filename}")

if __name__ == "__main__":
    create_placeholder_images()